async getCustomerIdByEmail(email) {
    await this._searchRateLimitBucket.throttle();
    try {
        const result = await this._stripe.customers.search({
            query: `email:"${email}"`,
            limit: 10,
            expand: ['data.subscriptions']
        });
        const customers = result.data;

        if (customers.length === 0) {
            return null;
        }

        if (customers.length === 1) {
            return customers[0].id;
        }

        return this._findCustomerWithLatestSubscription(customers);
    } catch (err) {
        debug(`getCustomerByEmail(${email}) -> ${err.type}:${err.message}`);
        return null;
    }
}

/**
 * Finds the customer with the most recent active subscription from a list of customers.
 *
 * @param {Array<import('stripe').Stripe.Customer>} customers
 * @returns {string|null} Customer ID with the latest subscription
 */
_findCustomerWithLatestSubscription(customers) {
    let latestCustomer = null;
    let latestSubscriptionTime = 0;

    for (const customer of customers) {
        const subscription = this._getMostRecentSubscription(customer);
        if (!subscription) {
            continue;
        }

        const subscriptionTime = subscription.current_period_end || 0;
        if (subscriptionTime > latestSubscriptionTime) {
            latestSubscriptionTime = subscriptionTime;
            latestCustomer = customer;
        }
    }

    return latestCustomer ? latestCustomer.id : null;
}

/**
 * Extracts the most recent subscription from a customer object.
 *
 * @param {import('stripe').Stripe.Customer} customer
 * @returns {import('stripe').Stripe.Subscription|null}
 */
_getMostRecentSubscription(customer) {
    if (!customer.subscriptions?.data?.length) {
        return null;
    }

    return customer.subscriptions.data.reduce((latest, subscription) => {
        const currentEnd = subscription.current_period_end || 0;
        const latestEnd = latest?.current_period_end || 0;
        return currentEnd > latestEnd ? subscription : latest;
    }, null);
}

