/**
 * Safely processes path for 'in' expression to determine whether parentheses should be preserved.
 * @param {ASTNode[]} path Path from parent to child node
 * @param {ASTNode} rootNode The root node of the for-loop initializer
 * @param {Object} buffer The current reports buffer
 * @returns {void}
 * @private
 */
function safeProcessInExpressionPath(path, rootNode, buffer) {
	const nodeToExclude = findExcludedNodeInInExpressionPath(path);

	if (nodeToExclude) {
		removeFromCurrentReportsBuffer(nodeToExclude);
	}
}

/**
 * Finds the node to exclude from reporting in an 'in' expression path.
 * @param {ASTNode[]} path Path from parent to child node
 * @returns {ASTNode|null} The node to exclude or null if none found
 * @private
 */
function findExcludedNodeInInExpressionPath(path) {
	let nodeToExclude = null;

	for (let i = 0; i < path.length; i++) {
		const pathNode = path[i];

		if (i < path.length - 1) {
			const nextPathNode = path[i + 1];

			if (
				isSafelyEnclosingInExpression(pathNode, nextPathNode)
			) {
				return null;
			}
		}

		if (isParenthesised(pathNode)) {
			if (isInCurrentReportsBuffer(pathNode)) {
				if (isParenthesisedTwice(pathNode)) {
					return null;
				}

				if (!nodeToExclude) {
					nodeToExclude = pathNode;
				}
			} else {
				return null;
			}
		}
	}

	return nodeToExclude;
}

